  'Social Psychology (Sociological)',
  'Social Psychology (Sociological)',
  'Social Psychology (Sociological) examines how selves, identities, emotions, attitudes, roles, groups, power, inequality, and collective action are produced through social interaction. Unlike a primarily individual-cognitive version of social psychology, this course emphasizes symbolic interaction, identity theory, dramaturgy, status processes, socialization, culture, networks, organizations, and institutions. Students learn to connect micro-level interaction with macro-level social structure.',
  $spsyjson${"slug": "social-psychology-sociological", "title": "Social Psychology (Sociological)", "description": "Social Psychology (Sociological) examines how selves, identities, emotions, attitudes, roles, groups, power, inequality, and collective action are produced through social interaction. Unlike a primarily individual-cognitive version of social psychology, this course emphasizes symbolic interaction, identity theory, dramaturgy, status processes, socialization, culture, networks, organizations, and institutions. Students learn to connect micro-level interaction with macro-level social structure.", "topics": [{"id": "df5c0799-058f-4c6f-93d0-28eba52240af", "type": "topic", "title": "What Makes Social Psychology Sociological", "description": "This opening unit distinguishes sociological social psychology from individual-centered approaches by emphasizing interaction, roles, culture, identity, power, groups, and social structure. Students learn to explain how selves and actions are shaped through social relations.", "children": [{"id": "9fb6a4ec-263f-462c-af2d-d23215221764", "type": "subtopic", "title": "Micro, meso, and macro connections", "children": [{"id": "8f4a9d3a-0622-4078-bf7d-62ff7777a659", "type": "concept", "title": "Situations and social structure"}, {"id": "bc819bd5-264c-4629-a578-4b1c50b957f8", "type": "concept", "title": "Interaction and institutions"}, {"id": "f8fc09c1-386c-4b39-8c1d-70d884a50772", "type": "concept", "title": "Biography and social history"}], "description": "Students learn how face-to-face interaction connects to organizations, institutions, inequality, and historical context."}, {"id": "d21c9477-b35d-4914-b178-644236a9cf4f", "type": "subtopic", "title": "Sociological versus psychological emphases", "children": [{"id": "a3739140-6129-4f71-9416-a32a3f4483cd", "type": "concept", "title": "Person and situation"}, {"id": "1452f1a4-006b-49de-aeaf-86f9fc61c1aa", "type": "concept", "title": "Social structure and meaning"}, {"id": "e2a7d7c4-e3c6-4617-bd18-7e817c2b2229", "type": "concept", "title": "Complementary levels of explanation"}], "description": "This subtopic compares sociological attention to roles, meanings, and groups with psychological attention to individual cognition and traits."}, {"id": "1ce2cd34-7366-4b35-96c2-2c10efdd9e09", "type": "subtopic", "title": "Core questions and traditions", "children": [{"id": "8f8d1ef4-5b4d-4cc0-bf3a-9e4870099848", "type": "concept", "title": "Symbolic interactionism"}, {"id": "cb486fb5-af4e-4a91-9a2d-a7c0781c3a09", "type": "concept", "title": "Identity and role theories"}, {"id": "b1ccd32e-049d-4ad2-89b5-80767c9e837f", "type": "concept", "title": "Group processes and social influence"}], "description": "Students survey the course's central traditions: symbolic interactionism, identity theory, social exchange, group processes, emotion, and social cognition."}]}, {"id": "a5359511-48f9-4874-80fe-4826dcf106d8", "type": "topic", "title": "Symbolic Interactionism, Meaning, and the Self", "description": "Symbolic interactionism is a foundation for sociological social psychology. It teaches students how meaning, language, interpretation, and interaction produce selves and social worlds.", "children": [{"id": "99cb3876-e6b3-416a-871c-9760a06a8b43", "type": "subtopic", "title": "Meaning and interpretation", "children": [{"id": "89a3b3b7-f2eb-4b3b-98b0-763a6586b958", "type": "concept", "title": "Symbols and language"}, {"id": "7f0284a9-233e-47c8-9fd2-6386c75048fc", "type": "concept", "title": "Definition of the situation"}, {"id": "fe7934cb-2d22-4fb9-aad1-a856753122ab", "type": "concept", "title": "Interpretive processes"}], "description": "Students learn that action depends on meanings people attach to objects, people, situations, and themselves."}, {"id": "e8ed9b0c-451e-40a6-9d0a-fdc3cf82697b", "type": "subtopic", "title": "Mead: mind, self, and society", "children": [{"id": "e4477b51-3d87-4d6d-8133-67c1ab263d56", "type": "concept", "title": "I and me"}, {"id": "46feb94d-1f26-4424-a6d2-1b9447ac66a8", "type": "concept", "title": "Role-taking"}, {"id": "51037899-6603-4c17-a0fc-ece1396d7d02", "type": "concept", "title": "Generalized other"}], "description": "This subtopic introduces role-taking, the generalized other, and the emergence of the self through social experience."}, {"id": "48358289-78d1-466e-b6a4-e46aa2af53c1", "type": "subtopic", "title": "Blumer and interactionist method", "children": [{"id": "6ef8a599-4227-46cc-aac7-a46dd34c4776", "type": "concept", "title": "Joint action"}, {"id": "2082f732-d0de-46d5-b9f5-2d23861db873", "type": "concept", "title": "Emergent meanings"}, {"id": "99fc247b-b156-44be-ace0-d0db91d1e371", "type": "concept", "title": "Naturalistic inquiry"}], "description": "Students examine how meanings are negotiated and revised through ongoing interaction."}]}, {"id": "3ec2db3f-878c-46b4-9dde-7efc6c8582fc", "type": "topic", "title": "Self, Identity, and Self-Concept", "description": "This unit explores how people develop, maintain, protect, and change identities in relation to others. Students learn to analyze identity as both personal experience and social location.", "children": [{"id": "269491a4-c14e-4c04-a7d6-c44c79003d45", "type": "subtopic", "title": "Self-concept and reflected appraisals", "children": [{"id": "4b9c44e9-c9e1-4011-aaae-64d3e78bab3d", "type": "concept", "title": "Looking-glass self"}, {"id": "03f8afc4-f58a-4dd5-ba22-bf66c4172338", "type": "concept", "title": "Reflected appraisals"}, {"id": "bf6d52f4-53c6-4943-b0ca-31862653a5ac", "type": "concept", "title": "Self-esteem and self-evaluation"}], "description": "Students learn how people understand themselves through feedback, comparison, and imagined judgments from others."}, {"id": "e417a142-de1d-426c-ab1c-a52a87e6c919", "type": "subtopic", "title": "Identity theory", "children": [{"id": "e544eeae-ebc8-4832-bec4-3d9ae96e3558", "type": "concept", "title": "Identity salience"}, {"id": "b3fce908-3815-40bf-9005-7b4a402a31ba", "type": "concept", "title": "Commitment and verification"}, {"id": "0264461a-0396-4096-9c59-ddafafcaa698", "type": "concept", "title": "Identity standards"}], "description": "This subtopic introduces identities as role-based meanings organized in hierarchies of salience and commitment."}, {"id": "d7c03934-ef06-47c5-8e6b-4af8d4c9578b", "type": "subtopic", "title": "Social identity and belonging", "children": [{"id": "9f947ab0-55a4-4984-bb11-e88bc93dd6eb", "type": "concept", "title": "In-groups and out-groups"}, {"id": "28f9aecb-7d3e-43ca-89de-3ea6ae2f9596", "type": "concept", "title": "Group identification"}, {"id": "48c81d5f-9f75-439e-8cdd-8f6268961631", "type": "concept", "title": "Categorization and belonging"}], "description": "Students examine how group memberships shape self-understanding, solidarity, bias, and collective behavior."}]}, {"id": "6fe7d5b7-5978-4616-bad9-1c367c5e105b", "type": "topic", "title": "Socialization Across the Life Course", "description": "Socialization is not only childhood learning; it is a lifelong process through which people acquire, negotiate, and sometimes reject roles, norms, and identities. This unit connects development with institutions and culture.", "children": [{"id": "d4d62beb-7d30-4ba5-b5de-feb5ebe340d6", "type": "subtopic", "title": "Primary and secondary socialization", "children": [{"id": "b88f3958-35e9-419e-82fc-6f3fe0d1a566", "type": "concept", "title": "Family and caregivers"}, {"id": "a5ffb153-b862-4e66-a487-6ecf348cdb74", "type": "concept", "title": "Schools and peers"}, {"id": "1d06665c-2950-4a4b-9f80-13c3f0746623", "type": "concept", "title": "Workplace and organizational socialization"}], "description": "Students compare early family socialization with later learning in schools, workplaces, peer groups, media, and organizations."}, {"id": "d1b1fb03-9a08-433f-926c-652f0e882ed3", "type": "subtopic", "title": "Life-course transitions", "children": [{"id": "fbc6117d-649f-43e4-94dc-bdc5eb9d7c91", "type": "concept", "title": "Adolescence and adulthood"}, {"id": "a077a4ba-5ada-4913-9ed3-1e7385667f62", "type": "concept", "title": "Aging and retirement"}, {"id": "0c867a2d-8e6f-4f57-935b-c923df0e25ac", "type": "concept", "title": "Turning points and trajectories"}], "description": "This subtopic examines how transitions reshape identity, expectations, networks, and obligations."}, {"id": "026e80bd-3d14-46d3-bd94-a303f51b0b43", "type": "subtopic", "title": "Resocialization and identity change", "children": [{"id": "60315531-81f9-447f-b7db-90622ba86c63", "type": "concept", "title": "Total institutions"}, {"id": "22a78335-ab83-4363-afc1-91c937ef47bf", "type": "concept", "title": "Conversion and recovery"}, {"id": "5d8fb071-3eff-4f20-bd7f-d85dff89c32e", "type": "concept", "title": "Professional identity formation"}], "description": "Students study institutions and experiences that actively remake the self."}]}, {"id": "66bd3e20-59e0-4ace-bd60-d3fcab468c06", "type": "topic", "title": "Roles, Statuses, and the Interaction Order", "description": "Roles and statuses organize expectations in everyday life. This unit helps students see interaction as structured performance rather than random behavior.", "children": [{"id": "f08fe980-f376-42a7-8b76-2ee1cdc6b78b", "type": "subtopic", "title": "Status, role, and role-set", "children": [{"id": "0e9d6d18-6e1a-49c0-8c1e-3c783431b0a0", "type": "concept", "title": "Ascribed and achieved status"}, {"id": "b936dd4c-6163-41b3-b931-e117ecf48c89", "type": "concept", "title": "Master status"}, {"id": "630c2760-9db9-4192-aa44-ba47a8c70c8a", "type": "concept", "title": "Role-sets"}], "description": "Students learn how social positions carry expectations, rights, obligations, and relationships to other positions."}, {"id": "777ad781-1b54-4d5a-b70b-6a36ec2f8f20", "type": "subtopic", "title": "Role conflict, strain, and exit", "children": [{"id": "e0ea6c43-678f-4a22-95d2-8b347ea68666", "type": "concept", "title": "Inter-role conflict"}, {"id": "b1a840ad-4a83-404c-803f-78ca4b5fd2c3", "type": "concept", "title": "Intra-role strain"}, {"id": "ec8f05ce-6992-4dd4-9c61-54661c3bf2e7", "type": "concept", "title": "Role exit"}], "description": "This subtopic examines what happens when expectations collide or when people leave identities and positions behind."}, {"id": "5668f3a3-74ca-4cd3-a2d3-f525957d45d7", "type": "subtopic", "title": "Goffman and dramaturgy", "children": [{"id": "c8eba5a9-0223-4c43-bf73-0c7ca18ddf50", "type": "concept", "title": "Presentation of self"}, {"id": "a101373a-b167-417c-93cf-b6fd8a245208", "type": "concept", "title": "Teams and audiences"}, {"id": "dce147a3-f4ec-4789-bef3-c9d61d19dbd5", "type": "concept", "title": "Face-work and embarrassment"}], "description": "Students analyze everyday interaction through performance, impression management, front stage, back stage, and face-work."}]}, {"id": "db923749-7830-4b5c-a11f-1cec3da12fb0", "type": "topic", "title": "Emotion, Affect, and Feeling Rules", "description": "Emotions are personal experiences, but they are also socially patterned, named, managed, and judged. This unit introduces sociological theories of emotion and emotional labor.", "children": [{"id": "f7e23963-7b4c-4ef3-b637-2f346e000f0f", "type": "subtopic", "title": "Emotion as social and cultural", "children": [{"id": "0dac0a40-1f48-4e53-8b33-0b7787c6d941", "type": "concept", "title": "Emotion vocabularies"}, {"id": "033a9764-99db-43db-9d48-ef017b65dc6c", "type": "concept", "title": "Cultural feeling rules"}, {"id": "e1748263-e32a-44e1-92fd-58ee242ac5cc", "type": "concept", "title": "Display rules"}], "description": "Students learn how societies shape what people feel, display, suppress, and interpret."}, {"id": "93708163-2fa6-4e89-b768-401523a7dd15", "type": "subtopic", "title": "Emotional labor", "children": [{"id": "efef7878-aa37-4308-b657-899668e60055", "type": "concept", "title": "Surface acting"}, {"id": "84b134df-bd88-4bc8-b54a-2d74708e194a", "type": "concept", "title": "Deep acting"}, {"id": "e54764bc-e533-401f-ba69-6ccde39cd1ef", "type": "concept", "title": "Burnout and alienation"}], "description": "This subtopic examines how workers manage feelings as part of service, care, leadership, and institutional roles."}, {"id": "fdfec16c-b2b1-426b-81dd-41b517144cae", "type": "subtopic", "title": "Emotion in groups and movements", "children": [{"id": "6aee12a9-d094-4346-b762-a0af8bcb88b8", "type": "concept", "title": "Collective emotion"}, {"id": "512b266d-506d-4887-b365-3b2796cd1dc3", "type": "concept", "title": "Moral shocks"}, {"id": "364a54a2-694f-4450-8732-757d68100b87", "type": "concept", "title": "Emotional energy"}], "description": "Students study how fear, shame, anger, pride, hope, and solidarity circulate through groups and publics."}]}, {"id": "a27b42d3-1460-4f81-b0e5-8f291ceaed86", "type": "topic", "title": "Attitudes, Values, Beliefs, and Persuasion", "description": "Attitudes and beliefs connect culture, cognition, identity, and action. This unit teaches students how people form, justify, change, and defend evaluations in social settings.", "children": [{"id": "bfef296e-6fe2-42de-9860-43c2e3c1e5d5", "type": "subtopic", "title": "Attitude structure and function", "children": [{"id": "25548887-e589-4cb7-83c7-68cd98b51417", "type": "concept", "title": "Cognitive, affective, and behavioral components"}, {"id": "60646e30-ce68-45c4-9bb3-ca8bd776332d", "type": "concept", "title": "Attitude strength"}, {"id": "46779f42-7273-46b5-8396-e71f0a59f712", "type": "concept", "title": "Values and ideology"}], "description": "Students learn how attitudes organize evaluation, identity, group belonging, and action."}, {"id": "e0a211f1-8f94-4858-b7f7-a67569f4091c", "type": "subtopic", "title": "Persuasion and influence", "children": [{"id": "1722db17-f903-4bcb-88cc-fb003db00873", "type": "concept", "title": "Source, message, and audience"}, {"id": "f6f16b32-d699-4300-8c81-20a79c2e3d7a", "type": "concept", "title": "Central and peripheral routes"}, {"id": "0ca2bd32-5c08-41d6-ad01-a668651cc6fc", "type": "concept", "title": "Credibility and trust"}], "description": "This subtopic introduces major routes of persuasion and the social conditions that make messages effective."}, {"id": "025f5a04-c1a6-4102-bfc3-668abf97a161", "type": "subtopic", "title": "Cognitive dissonance and justification", "children": [{"id": "cfba193d-11aa-40b7-bcd3-1137c82e9608", "type": "concept", "title": "Dissonance reduction"}, {"id": "966a692f-7ee4-4f00-8d13-985c80b6f1d3", "type": "concept", "title": "Self-justification"}, {"id": "1e060770-a017-441a-bbf3-e7c0de330be9", "type": "concept", "title": "Commitment and consistency"}], "description": "Students examine how people reconcile inconsistent beliefs, actions, and identities."}]}, {"id": "5d383f7a-bb54-4eca-88a4-057a1c44ddb7", "type": "topic", "title": "Social Cognition, Attribution, and Categorization", "description": "Sociological social psychology uses cognition carefully: not as isolated mental machinery, but as thinking shaped by culture, groups, institutions, and interaction. This unit develops that bridge.", "children": [{"id": "e6854cca-38ed-43d5-880c-107e9fa6a575", "type": "subtopic", "title": "Schemas and social perception", "children": [{"id": "8168ba35-1225-43e0-84e6-ff14f9aee389", "type": "concept", "title": "Schemas and scripts"}, {"id": "a946f529-a6ee-4e97-b85a-89a4256d0f35", "type": "concept", "title": "Priming and salience"}, {"id": "9d7e697c-eeb4-442e-adfb-5a2ee35509b0", "type": "concept", "title": "Stereotype activation"}], "description": "Students learn how categories, scripts, and expectations guide perception and interpretation."}, {"id": "a0d9d552-26e3-4291-a199-40a995633e3a", "type": "subtopic", "title": "Attribution and explanation", "children": [{"id": "d30e4cfb-b8ca-45ec-b67d-49998202114e", "type": "concept", "title": "Internal and external attribution"}, {"id": "67015972-2cb3-40f6-9396-a4e011242fee", "type": "concept", "title": "Fundamental attribution error"}, {"id": "43f7edca-9a7f-43e5-8c15-a1b6a107b6ac", "type": "concept", "title": "Actor-observer patterns"}], "description": "This subtopic explores how people explain behavior and how those explanations shape blame, trust, and inequality."}, {"id": "ecb9a4b5-e65a-4761-a6b6-53fa13f4d92d", "type": "subtopic", "title": "Bias, heuristics, and social judgment", "children": [{"id": "74077dbd-ca3f-49cf-bca1-6714ba4c7ad6", "type": "concept", "title": "Availability and representativeness"}, {"id": "94972f00-e1e5-49cf-9eb1-d58f09c86108", "type": "concept", "title": "Confirmation bias"}, {"id": "b9a71437-95c2-4739-975d-2b8ea1301762", "type": "concept", "title": "Motivated reasoning"}], "description": "Students examine shortcuts and biases as socially consequential patterns of reasoning."}]}, {"id": "2d0fe5fb-561f-4cbe-8cd8-f031c5f61608", "type": "topic", "title": "Conformity, Compliance, Obedience, and Resistance", "description": "Social influence is central to understanding social order. Students learn why people follow norms, obey authority, comply with requests, and sometimes resist pressure.", "children": [{"id": "0b4e884b-4a27-47d0-97db-f908c942fd19", "type": "subtopic", "title": "Conformity and normative pressure", "children": [{"id": "618bdb86-9b3e-4b3b-821a-3d9c3f72634a", "type": "concept", "title": "Normative influence"}, {"id": "17bc2cda-c63e-44f3-b3d4-bdf6f918de2f", "type": "concept", "title": "Informational influence"}, {"id": "8efd7382-8a82-488d-bc0d-e68df634d898", "type": "concept", "title": "Pluralistic ignorance"}], "description": "Students analyze how group expectations shape behavior, speech, style, and belief."}, {"id": "8e99e7bc-8f3b-4891-9613-43ecbba7adc1", "type": "subtopic", "title": "Compliance and obedience", "children": [{"id": "a3631e3a-392c-486d-bfbd-1d08a1c98dac", "type": "concept", "title": "Authority and legitimacy"}, {"id": "72d782b2-0b28-4044-ab04-60a0b24990f6", "type": "concept", "title": "Foot-in-the-door and door-in-the-face"}, {"id": "69533529-429f-4e9b-8c5e-5be300e684e9", "type": "concept", "title": "Diffusion of responsibility"}], "description": "This subtopic examines how authority, legitimacy, gradual commitment, and institutional setting affect action."}, {"id": "1a48fa22-d216-4e4c-b222-325a8bd7caf8", "type": "subtopic", "title": "Resistance and dissent", "children": [{"id": "199527cd-aed5-4a45-826c-e85e5661a3f2", "type": "concept", "title": "Minority influence"}, {"id": "c9e09907-05be-4993-90ee-b6549b309afd", "type": "concept", "title": "Whistleblowing"}, {"id": "d0d8bda6-8c83-45de-a8ce-9f6cd3b2840b", "type": "concept", "title": "Everyday resistance"}], "description": "Students study how people challenge norms and authority through voice, exit, refusal, and collective action."}]}, {"id": "f1d8cfe8-04f7-4e81-af44-4647f6c14bb3", "type": "topic", "title": "Group Processes, Teams, and Collective Behavior", "description": "Groups are more than collections of individuals. This unit examines how group structure, leadership, cohesion, status, and conflict shape decisions and behavior.", "children": [{"id": "6fcbf12d-fa60-48ff-ba44-4b8792aa3fcc", "type": "subtopic", "title": "Group formation and cohesion", "children": [{"id": "21b4a400-32e3-471f-a84a-ec7881e988f5", "type": "concept", "title": "Membership and boundaries"}, {"id": "fc077eef-aa12-4c99-bdcc-96b3a5de09ec", "type": "concept", "title": "Cohesion and solidarity"}, {"id": "49a68fc8-f739-44e9-8e0d-541eb222fb3f", "type": "concept", "title": "Group identity"}], "description": "Students learn why groups form, how members bond, and when cohesion helps or harms performance."}, {"id": "2cc4ccee-9567-402c-b274-7df4c526ec95", "type": "subtopic", "title": "Leadership, status, and decision-making", "children": [{"id": "47c23294-704d-4b78-a923-df2e6d18a907", "type": "concept", "title": "Leadership styles"}, {"id": "eb42306a-db6e-4cf5-a22d-62050a9a0cf7", "type": "concept", "title": "Status characteristics"}, {"id": "406aa036-5913-440c-86d2-336985fa1eb8", "type": "concept", "title": "Groupthink and polarization"}], "description": "This subtopic studies leadership emergence, status hierarchies, groupthink, polarization, and collective judgment."}, {"id": "fda26adc-985d-48be-b17c-6aabe9985270", "type": "subtopic", "title": "Collective behavior", "children": [{"id": "210d4578-1cb8-4318-bc7b-7b087938f027", "type": "concept", "title": "Emergent norms"}, {"id": "4dc8294b-49a3-4839-ac44-d10236b0d5fb", "type": "concept", "title": "Rumor and contagion"}, {"id": "ba57d3a4-6179-4732-8110-04b53a2c9138", "type": "concept", "title": "Crowds and publics"}], "description": "Students examine crowds, publics, rumors, fads, panics, and emergent group action."}]}, {"id": "4a56334a-c2ad-4d76-97b8-b53ca49534e1", "type": "topic", "title": "Power, Status, Dominance, and Inequality in Interaction", "description": "Power and inequality appear not only in institutions but also in talk, attention, deference, interruption, trust, and evaluation. This unit teaches students to see inequality at the interactional level.", "children": [{"id": "95d0da3f-d686-4365-a64a-62b8f49b7b37", "type": "subtopic", "title": "Status characteristics theory", "children": [{"id": "8907ba29-a81d-4316-9261-ad69c2c3919c", "type": "concept", "title": "Diffuse status characteristics"}, {"id": "1db2f49a-fc55-445b-8e62-20f741f30185", "type": "concept", "title": "Performance expectations"}, {"id": "be2270eb-8ccc-4ee9-9b3e-401179c3fc3b", "type": "concept", "title": "Status generalization"}], "description": "Students learn how status beliefs shape competence expectations and participation in groups."}, {"id": "795faa2f-28ec-4c6a-8627-19bd2ab20413", "type": "subtopic", "title": "Dominance and deference", "children": [{"id": "a2c02112-c6b2-4799-977e-75db8b0dbecc", "type": "concept", "title": "Turn-taking and interruption"}, {"id": "627b5be9-817f-4a3d-bc66-dfc1bb8a00bd", "type": "concept", "title": "Deference and demeanor"}, {"id": "5018b8c1-3f70-462c-9364-3e84b21ef062", "type": "concept", "title": "Spatial and embodied power"}], "description": "This subtopic examines how power is enacted in bodies, language, emotion, space, and interaction rituals."}, {"id": "37e69fdf-845d-423a-bf2f-319d6ac6ea96", "type": "subtopic", "title": "Intersectional interaction", "children": [{"id": "09c344a2-c54c-46ce-995e-e1bc54a1aa1c", "type": "concept", "title": "Microaggressions"}, {"id": "aff54629-c38c-4c2c-b145-ca79b1effce8", "type": "concept", "title": "Stereotype threat"}, {"id": "f05ad1a4-adc8-4af5-b2fa-b7798ffb0767", "type": "concept", "title": "Identity safety"}], "description": "Students analyze how race, class, gender, sexuality, age, disability, and citizenship shape everyday encounters."}]}, {"id": "949dfcc5-d79a-4243-94b8-a555defb029a", "type": "topic", "title": "Prejudice, Stereotyping, Discrimination, and Intergroup Relations", "description": "This unit connects identity, cognition, institutions, and group conflict. Students learn how bias operates at individual, interactional, organizational, and structural levels.", "children": [{"id": "b03d0957-3d81-4394-bf3a-ad9f6477b8c3", "type": "subtopic", "title": "Stereotypes and categorization", "children": [{"id": "8e2d47f3-eed2-42be-9b49-0970e569ecea", "type": "concept", "title": "Stereotype content"}, {"id": "efdba6cb-f3b0-4ce4-8afb-3ec930a61390", "type": "concept", "title": "Implicit and explicit bias"}, {"id": "3dbaabb0-0274-4923-840b-c329c9af4a5f", "type": "concept", "title": "Essentialism"}], "description": "Students examine how categories simplify social worlds and reproduce inequality."}, {"id": "fc86fc3d-682a-45e9-b995-185029805664", "type": "subtopic", "title": "Prejudice and discrimination", "children": [{"id": "091652da-9667-416d-94a7-63dd3419fc70", "type": "concept", "title": "Affective prejudice"}, {"id": "c8a829a8-026a-44ba-a339-f92ed274dd5e", "type": "concept", "title": "Behavioral discrimination"}, {"id": "e41390f5-8b4a-4e5a-8f8f-16ba29b2726c", "type": "concept", "title": "Institutional discrimination"}], "description": "This subtopic distinguishes attitudes, emotions, behaviors, and institutional outcomes."}, {"id": "ada2379b-314b-4208-8826-c1388b0024a7", "type": "subtopic", "title": "Intergroup contact and conflict", "children": [{"id": "5ebea79a-a49b-49b4-8089-9dcf95cbf221", "type": "concept", "title": "Contact hypothesis"}, {"id": "39db3259-c6f7-4e0d-bfd3-a10d534d7329", "type": "concept", "title": "Realistic group conflict"}, {"id": "0c4e79db-b5fc-49f4-8688-7a5956bfcc19", "type": "concept", "title": "Common ingroup identity"}], "description": "Students assess when contact reduces prejudice and when competition or threat intensifies it."}]}, {"id": "a55f6d45-94b8-45bd-adaa-488c2c0bedde", "type": "topic", "title": "Culture, Language, Frames, and Interaction", "description": "Culture gives people repertoires for interpreting situations and acting with others. This unit examines language, frames, narratives, symbols, and cultural toolkits in everyday life.", "children": [{"id": "17459049-84f1-40fd-b3bd-4aaf6c02c48a", "type": "subtopic", "title": "Frames and definitions of the situation", "children": [{"id": "f8196007-1fa3-4ba1-adb4-79545d1a5721", "type": "concept", "title": "Frame alignment"}, {"id": "ac40ec5b-2e61-46d2-8e1a-f19eae360d63", "type": "concept", "title": "Keying and footing"}, {"id": "4e49149b-a951-4cf1-b900-4a2da47dc7af", "type": "concept", "title": "Situational cues"}], "description": "Students learn how frames organize attention, meaning, and appropriate action."}, {"id": "c8b69447-ccf7-41b7-921b-946e497c4eca", "type": "subtopic", "title": "Language and interaction", "children": [{"id": "f06e9e81-15b4-42e5-991c-48ff35da49c7", "type": "concept", "title": "Accounts and excuses"}, {"id": "30971692-c553-4ede-b541-fdf96e97f718", "type": "concept", "title": "Narrative identity"}, {"id": "702d40ec-46ee-43f6-9ee5-3923990e026b", "type": "concept", "title": "Symbolic boundaries"}], "description": "This subtopic studies conversation, categorization, accounts, narratives, and symbolic boundaries."}, {"id": "258d9881-eb3b-4ef8-bb06-69d0a5741483", "type": "subtopic", "title": "Culture as toolkit", "children": [{"id": "dcd4f782-6a9e-4b0d-9a80-24a7c54e9fa4", "type": "concept", "title": "Habits and repertoires"}, {"id": "3b5db67d-c74a-4589-8be0-789a40effc89", "type": "concept", "title": "Cultural capital"}, {"id": "c04f3b2b-2bba-4b62-bd2b-e6cf8edab235", "type": "concept", "title": "Moral vocabularies"}], "description": "Students examine how people draw on cultural repertoires to solve problems and justify action."}]}, {"id": "be4fab72-89b8-4b55-9c13-b01e84e593e8", "type": "topic", "title": "Networks, Social Capital, and Diffusion", "description": "Social life moves through relationships. This unit teaches students how networks shape identity, information, influence, belonging, inequality, and social change.", "children": [{"id": "5af4b9a0-d337-4e20-9b7f-8d6945295661", "type": "subtopic", "title": "Network structure", "children": [{"id": "9ed0c1f3-c511-4d6e-864f-c569337c5d7e", "type": "concept", "title": "Nodes and ties"}, {"id": "53df93b5-fa2a-485f-9579-2324fe83334e", "type": "concept", "title": "Density and centrality"}, {"id": "b239f66b-238a-41f4-9819-f7d3b98dac95", "type": "concept", "title": "Homophily"}], "description": "Students learn basic network ideas and how ties pattern opportunities and constraints."}, {"id": "fb5ec94b-c403-4ce1-b5c6-283dc10f656b", "type": "subtopic", "title": "Social capital and support", "children": [{"id": "2d92e968-949b-4b2b-b7f1-c5a9cb581377", "type": "concept", "title": "Bonding and bridging capital"}, {"id": "f4b10e61-b541-4e67-b71d-62a4b6ef9db4", "type": "concept", "title": "Strong and weak ties"}, {"id": "ef97e90c-484e-45b8-8785-70674d5da413", "type": "concept", "title": "Support and reciprocity"}], "description": "This subtopic examines how relationships provide resources, obligations, trust, and exclusion."}, {"id": "b91ec76a-f4ee-49c4-9178-779cd86022f0", "type": "subtopic", "title": "Diffusion and contagion", "children": [{"id": "dbecbda6-e68c-4c6e-977e-732a92ce07b8", "type": "concept", "title": "Threshold models"}, {"id": "010488c9-1f1b-440c-aa56-49cf21fa1584", "type": "concept", "title": "Opinion leaders"}, {"id": "0617ab3c-42cc-49ef-b19a-888d352fe7eb", "type": "concept", "title": "Network cascades"}], "description": "Students study how ideas, practices, emotions, innovations, and behaviors spread."}]}, {"id": "e4e686db-16e8-4c2b-9f43-1642238da2b0", "type": "topic", "title": "Everyday Life, Organizations, and Institutions", "description": "Sociological social psychology is especially strong at showing how everyday encounters are embedded in organizations and institutions. This unit connects microinteraction with schools, workplaces, medicine, law, religion, and media.", "children": [{"id": "00dea898-fc5d-4a40-a0b8-fed9aa03bfe3", "type": "subtopic", "title": "Organizations as interaction orders", "children": [{"id": "0b23007b-38ef-4ec3-92ab-2b6fe28247fd", "type": "concept", "title": "Workplace roles"}, {"id": "8da2208b-249b-49ec-8315-be08f3059722", "type": "concept", "title": "Professional identity"}, {"id": "e8a4fee7-0579-4af6-8d7b-644afd822542", "type": "concept", "title": "Organizational scripts"}], "description": "Students analyze organizations as settings where roles, emotions, power, and identity are managed."}, {"id": "0e78a4c4-69c1-430d-a525-6953d3de6aaa", "type": "subtopic", "title": "Institutional encounters", "children": [{"id": "0ed05577-dee2-4c62-8da9-ac174c49899e", "type": "concept", "title": "Street-level bureaucracy"}, {"id": "9db9f187-869c-4048-9d2c-22c93ab86597", "type": "concept", "title": "Institutional talk"}, {"id": "2ed44f41-c303-4e2f-a0bf-1c17211b4649", "type": "concept", "title": "Classification and case processing"}], "description": "This subtopic examines interactions with schools, courts, clinics, bureaucracies, and service systems."}, {"id": "d11773f7-8a6a-4db6-bc7f-eba3dd104554", "type": "subtopic", "title": "Media and digital interaction", "children": [{"id": "92c79daf-3242-460c-ab3c-3b0f3c759309", "type": "concept", "title": "Online self-presentation"}, {"id": "639c4848-6816-473a-9864-8488fdb6fd4d", "type": "concept", "title": "Likes and metrics"}, {"id": "f9070ffb-dfe2-463a-87fd-ae5e21b032ba", "type": "concept", "title": "Context collapse"}], "description": "Students explore how platforms reshape self-presentation, attention, comparison, and public identity."}]}, {"id": "cf993c1f-b873-494d-995a-6e081ae30db6", "type": "topic", "title": "Micro-Foundations of Social Movements and Collective Action", "description": "Social movements depend on identity, emotion, networks, framing, solidarity, and strategic interaction. This unit shows how large-scale change rests on small-scale social psychology.", "children": [{"id": "085f30b1-4ffe-4f95-a462-6d585c0ce5eb", "type": "subtopic", "title": "Collective identity", "children": [{"id": "8ee64d71-6cf8-481e-8a6f-63a2dd0bdd67", "type": "concept", "title": "Boundary work"}, {"id": "4def021f-a876-4e28-82d2-df805dfd2ba9", "type": "concept", "title": "Solidarity"}, {"id": "81784457-8bd1-46e0-87d7-5a7967b180b3", "type": "concept", "title": "Identity narratives"}], "description": "Students learn how movements create a shared sense of we, opponents, grievances, and goals."}, {"id": "835ac8d2-eef6-43ec-8ba7-d39d5270a61b", "type": "subtopic", "title": "Mobilization and networks", "children": [{"id": "590008aa-7ffb-429b-9837-35aadfb994f0", "type": "concept", "title": "Recruitment networks"}, {"id": "3bbe1000-e3c1-4ca6-b186-a6ac1d671fdc", "type": "concept", "title": "Biographical availability"}, {"id": "2bbf7ecc-615a-410c-ba5c-c26f1ef561aa", "type": "concept", "title": "Emotional energy"}], "description": "This subtopic examines how ties, organizations, leaders, and emotions draw people into action."}, {"id": "566bf2bb-38fa-4cd1-bd28-8cc193d92937", "type": "subtopic", "title": "Frames, tactics, and outcomes", "children": [{"id": "2325396b-1894-4003-8b1b-80ae9faf425c", "type": "concept", "title": "Diagnostic and prognostic frames"}, {"id": "d31ef967-fa81-4400-b4c8-8ee9814f87f5", "type": "concept", "title": "Repertoires of contention"}, {"id": "a1ff154f-7319-4312-84fc-c61418009289", "type": "concept", "title": "Backlash and countermovements"}], "description": "Students analyze how movements persuade publics, sustain commitment, and face backlash."}]}, {"id": "020b175f-2907-4709-aecc-9a7c5500b662", "type": "topic", "title": "Research Methods for Sociological Social Psychology", "description": "A comprehensive course should teach students not only theories, but how evidence is produced. This unit introduces the main methods used to study interaction, identity, groups, and social influence.", "children": [{"id": "21941521-ded8-4a60-9573-ff2b1c9ebe28", "type": "subtopic", "title": "Surveys, experiments, and mixed methods", "children": [{"id": "3d415a85-db96-4d5e-adac-519b238936e2", "type": "concept", "title": "Survey design"}, {"id": "bc5a5f2c-1f0c-4784-b161-f817fa92995f", "type": "concept", "title": "Experiments and vignettes"}, {"id": "ecc3824f-ba58-45d8-8635-b3d8a4748730", "type": "concept", "title": "Mixed-method designs"}], "description": "Students learn how researchers measure attitudes, identities, networks, influence, and group dynamics."}, {"id": "57eaa26e-0563-46e7-85cf-edcde7c27a89", "type": "subtopic", "title": "Interviews, ethnography, and conversation data", "children": [{"id": "82d09b2f-b32f-49e2-8431-fd72a491658e", "type": "concept", "title": "Interview protocols"}, {"id": "3dbd7bee-17fd-4b3c-bbed-b9886e3fedc4", "type": "concept", "title": "Participant observation"}, {"id": "574a3b6f-4a0f-406c-a5a1-4c6623259b35", "type": "concept", "title": "Conversation and discourse analysis"}], "description": "This subtopic introduces methods for studying meaning, performance, and interaction in depth."}, {"id": "ca35c910-d9d0-4c7a-a3f7-4f814a90054d", "type": "subtopic", "title": "Ethics, replication, and open science", "children": [{"id": "56541cdd-696e-4a75-af5c-251e6a43c15a", "type": "concept", "title": "IRB and consent"}, {"id": "a84e2c8a-0c8b-49ed-8e21-7d0cbde7de8a", "type": "concept", "title": "Preregistration"}, {"id": "184c6c7c-26b9-42df-bf75-8beb0733fa31", "type": "concept", "title": "Data sharing and confidentiality"}], "description": "Students examine human-subjects ethics, transparency, reproducibility, and the responsible interpretation of sensitive findings."}]}, {"id": "a81f654a-8fe1-4fb5-aa77-88a96054df7b", "type": "topic", "title": "Capstone: Interaction Analysis, Identity Case Study, or Group Process Project", "description": "The course culminates in a project where students apply theory and evidence to a real interactional setting, identity process, group dynamic, or social movement. The capstone turns concepts into sociological analysis.", "children": [{"id": "eb33d1c2-f67e-4da1-98e8-b8ed2497f8ae", "type": "subtopic", "title": "Question and theoretical frame", "children": [{"id": "42f7edc4-5f69-46bc-887d-b229cec157e5", "type": "concept", "title": "Research question"}, {"id": "5f0550b6-342d-4d8b-8561-1d731814f511", "type": "concept", "title": "Concept map"}, {"id": "ff512b81-6a32-4420-8a63-5a1d6b71823a", "type": "concept", "title": "Scope and case boundaries"}], "description": "Students define a focused question and choose theories that explain the case."}, {"id": "0070870f-5bc0-45b0-bd7c-4fee9dd3e008", "type": "subtopic", "title": "Evidence portfolio", "children": [{"id": "b2181aa7-0685-475d-a33d-a901cdf0d488", "type": "concept", "title": "Observation or interview evidence"}, {"id": "56a556f3-53fe-41cd-b1c4-1d51cfb6bf88", "type": "concept", "title": "Survey, media, or archival evidence"}, {"id": "bb6a1e03-7232-4bcb-a7c8-817b55827175", "type": "concept", "title": "Ethical documentation"}], "description": "This subtopic requires students to gather empirical material and evaluate its strengths and limits."}, {"id": "72bd5219-3720-4c2b-bc98-c06f8340fc73", "type": "subtopic", "title": "Analysis and public presentation", "children": [{"id": "286df06b-1e2b-452a-aa29-73eba61e5bff", "type": "concept", "title": "Claim-evidence-reasoning"}, {"id": "46d3d9a2-7a69-4aca-8686-8666cf119d03", "type": "concept", "title": "Limitations and reflexivity"}, {"id": "f676cbe6-692b-4798-8653-4f7bd2eaa418", "type": "concept", "title": "Presentation or brief"}], "description": "Students produce a concise research report or presentation linking evidence, theory, and implications."}]}], "dbBacked": true}$spsyjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'social-psychology-sociological'
);

update public.learning_paths
set
  title = 'Social Psychology (Sociological)',
  goal = 'Social Psychology (Sociological)',
  summary = 'Social Psychology (Sociological) examines how selves, identities, emotions, attitudes, roles, groups, power, inequality, and collective action are produced through social interaction. Unlike a primarily individual-cognitive version of social psychology, this course emphasizes symbolic interaction, identity theory, dramaturgy, status processes, socialization, culture, networks, organizations, and institutions. Students learn to connect micro-level interaction with macro-level social structure.',
  data = $spsyjson${"slug": "social-psychology-sociological", "title": "Social Psychology (Sociological)", "description": "Social Psychology (Sociological) examines how selves, identities, emotions, attitudes, roles, groups, power, inequality, and collective action are produced through social interaction. Unlike a primarily individual-cognitive version of social psychology, this course emphasizes symbolic interaction, identity theory, dramaturgy, status processes, socialization, culture, networks, organizations, and institutions. Students learn to connect micro-level interaction with macro-level social structure.", "topics": [{"id": "df5c0799-058f-4c6f-93d0-28eba52240af", "type": "topic", "title": "What Makes Social Psychology Sociological", "description": "This opening unit distinguishes sociological social psychology from individual-centered approaches by emphasizing interaction, roles, culture, identity, power, groups, and social structure. Students learn to explain how selves and actions are shaped through social relations.", "children": [{"id": "9fb6a4ec-263f-462c-af2d-d23215221764", "type": "subtopic", "title": "Micro, meso, and macro connections", "children": [{"id": "8f4a9d3a-0622-4078-bf7d-62ff7777a659", "type": "concept", "title": "Situations and social structure"}, {"id": "bc819bd5-264c-4629-a578-4b1c50b957f8", "type": "concept", "title": "Interaction and institutions"}, {"id": "f8fc09c1-386c-4b39-8c1d-70d884a50772", "type": "concept", "title": "Biography and social history"}], "description": "Students learn how face-to-face interaction connects to organizations, institutions, inequality, and historical context."}, {"id": "d21c9477-b35d-4914-b178-644236a9cf4f", "type": "subtopic", "title": "Sociological versus psychological emphases", "children": [{"id": "a3739140-6129-4f71-9416-a32a3f4483cd", "type": "concept", "title": "Person and situation"}, {"id": "1452f1a4-006b-49de-aeaf-86f9fc61c1aa", "type": "concept", "title": "Social structure and meaning"}, {"id": "e2a7d7c4-e3c6-4617-bd18-7e817c2b2229", "type": "concept", "title": "Complementary levels of explanation"}], "description": "This subtopic compares sociological attention to roles, meanings, and groups with psychological attention to individual cognition and traits."}, {"id": "1ce2cd34-7366-4b35-96c2-2c10efdd9e09", "type": "subtopic", "title": "Core questions and traditions", "children": [{"id": "8f8d1ef4-5b4d-4cc0-bf3a-9e4870099848", "type": "concept", "title": "Symbolic interactionism"}, {"id": "cb486fb5-af4e-4a91-9a2d-a7c0781c3a09", "type": "concept", "title": "Identity and role theories"}, {"id": "b1ccd32e-049d-4ad2-89b5-80767c9e837f", "type": "concept", "title": "Group processes and social influence"}], "description": "Students survey the course's central traditions: symbolic interactionism, identity theory, social exchange, group processes, emotion, and social cognition."}]}, {"id": "a5359511-48f9-4874-80fe-4826dcf106d8", "type": "topic", "title": "Symbolic Interactionism, Meaning, and the Self", "description": "Symbolic interactionism is a foundation for sociological social psychology. It teaches students how meaning, language, interpretation, and interaction produce selves and social worlds.", "children": [{"id": "99cb3876-e6b3-416a-871c-9760a06a8b43", "type": "subtopic", "title": "Meaning and interpretation", "children": [{"id": "89a3b3b7-f2eb-4b3b-98b0-763a6586b958", "type": "concept", "title": "Symbols and language"}, {"id": "7f0284a9-233e-47c8-9fd2-6386c75048fc", "type": "concept", "title": "Definition of the situation"}, {"id": "fe7934cb-2d22-4fb9-aad1-a856753122ab", "type": "concept", "title": "Interpretive processes"}], "description": "Students learn that action depends on meanings people attach to objects, people, situations, and themselves."}, {"id": "e8ed9b0c-451e-40a6-9d0a-fdc3cf82697b", "type": "subtopic", "title": "Mead: mind, self, and society", "children": [{"id": "e4477b51-3d87-4d6d-8133-67c1ab263d56", "type": "concept", "title": "I and me"}, {"id": "46feb94d-1f26-4424-a6d2-1b9447ac66a8", "type": "concept", "title": "Role-taking"}, {"id": "51037899-6603-4c17-a0fc-ece1396d7d02", "type": "concept", "title": "Generalized other"}], "description": "This subtopic introduces role-taking, the generalized other, and the emergence of the self through social experience."}, {"id": "48358289-78d1-466e-b6a4-e46aa2af53c1", "type": "subtopic", "title": "Blumer and interactionist method", "children": [{"id": "6ef8a599-4227-46cc-aac7-a46dd34c4776", "type": "concept", "title": "Joint action"}, {"id": "2082f732-d0de-46d5-b9f5-2d23861db873", "type": "concept", "title": "Emergent meanings"}, {"id": "99fc247b-b156-44be-ace0-d0db91d1e371", "type": "concept", "title": "Naturalistic inquiry"}], "description": "Students examine how meanings are negotiated and revised through ongoing interaction."}]}, {"id": "3ec2db3f-878c-46b4-9dde-7efc6c8582fc", "type": "topic", "title": "Self, Identity, and Self-Concept", "description": "This unit explores how people develop, maintain, protect, and change identities in relation to others. Students learn to analyze identity as both personal experience and social location.", "children": [{"id": "269491a4-c14e-4c04-a7d6-c44c79003d45", "type": "subtopic", "title": "Self-concept and reflected appraisals", "children": [{"id": "4b9c44e9-c9e1-4011-aaae-64d3e78bab3d", "type": "concept", "title": "Looking-glass self"}, {"id": "03f8afc4-f58a-4dd5-ba22-bf66c4172338", "type": "concept", "title": "Reflected appraisals"}, {"id": "bf6d52f4-53c6-4943-b0ca-31862653a5ac", "type": "concept", "title": "Self-esteem and self-evaluation"}], "description": "Students learn how people understand themselves through feedback, comparison, and imagined judgments from others."}, {"id": "e417a142-de1d-426c-ab1c-a52a87e6c919", "type": "subtopic", "title": "Identity theory", "children": [{"id": "e544eeae-ebc8-4832-bec4-3d9ae96e3558", "type": "concept", "title": "Identity salience"}, {"id": "b3fce908-3815-40bf-9005-7b4a402a31ba", "type": "concept", "title": "Commitment and verification"}, {"id": "0264461a-0396-4096-9c59-ddafafcaa698", "type": "concept", "title": "Identity standards"}], "description": "This subtopic introduces identities as role-based meanings organized in hierarchies of salience and commitment."}, {"id": "d7c03934-ef06-47c5-8e6b-4af8d4c9578b", "type": "subtopic", "title": "Social identity and belonging", "children": [{"id": "9f947ab0-55a4-4984-bb11-e88bc93dd6eb", "type": "concept", "title": "In-groups and out-groups"}, {"id": "28f9aecb-7d3e-43ca-89de-3ea6ae2f9596", "type": "concept", "title": "Group identification"}, {"id": "48c81d5f-9f75-439e-8cdd-8f6268961631", "type": "concept", "title": "Categorization and belonging"}], "description": "Students examine how group memberships shape self-understanding, solidarity, bias, and collective behavior."}]}, {"id": "6fe7d5b7-5978-4616-bad9-1c367c5e105b", "type": "topic", "title": "Socialization Across the Life Course", "description": "Socialization is not only childhood learning; it is a lifelong process through which people acquire, negotiate, and sometimes reject roles, norms, and identities. This unit connects development with institutions and culture.", "children": [{"id": "d4d62beb-7d30-4ba5-b5de-feb5ebe340d6", "type": "subtopic", "title": "Primary and secondary socialization", "children": [{"id": "b88f3958-35e9-419e-82fc-6f3fe0d1a566", "type": "concept", "title": "Family and caregivers"}, {"id": "a5ffb153-b862-4e66-a487-6ecf348cdb74", "type": "concept", "title": "Schools and peers"}, {"id": "1d06665c-2950-4a4b-9f80-13c3f0746623", "type": "concept", "title": "Workplace and organizational socialization"}], "description": "Students compare early family socialization with later learning in schools, workplaces, peer groups, media, and organizations."}, {"id": "d1b1fb03-9a08-433f-926c-652f0e882ed3", "type": "subtopic", "title": "Life-course transitions", "children": [{"id": "fbc6117d-649f-43e4-94dc-bdc5eb9d7c91", "type": "concept", "title": "Adolescence and adulthood"}, {"id": "a077a4ba-5ada-4913-9ed3-1e7385667f62", "type": "concept", "title": "Aging and retirement"}, {"id": "0c867a2d-8e6f-4f57-935b-c923df0e25ac", "type": "concept", "title": "Turning points and trajectories"}], "description": "This subtopic examines how transitions reshape identity, expectations, networks, and obligations."}, {"id": "026e80bd-3d14-46d3-bd94-a303f51b0b43", "type": "subtopic", "title": "Resocialization and identity change", "children": [{"id": "60315531-81f9-447f-b7db-90622ba86c63", "type": "concept", "title": "Total institutions"}, {"id": "22a78335-ab83-4363-afc1-91c937ef47bf", "type": "concept", "title": "Conversion and recovery"}, {"id": "5d8fb071-3eff-4f20-bd7f-d85dff89c32e", "type": "concept", "title": "Professional identity formation"}], "description": "Students study institutions and experiences that actively remake the self."}]}, {"id": "66bd3e20-59e0-4ace-bd60-d3fcab468c06", "type": "topic", "title": "Roles, Statuses, and the Interaction Order", "description": "Roles and statuses organize expectations in everyday life. This unit helps students see interaction as structured performance rather than random behavior.", "children": [{"id": "f08fe980-f376-42a7-8b76-2ee1cdc6b78b", "type": "subtopic", "title": "Status, role, and role-set", "children": [{"id": "0e9d6d18-6e1a-49c0-8c1e-3c783431b0a0", "type": "concept", "title": "Ascribed and achieved status"}, {"id": "b936dd4c-6163-41b3-b931-e117ecf48c89", "type": "concept", "title": "Master status"}, {"id": "630c2760-9db9-4192-aa44-ba47a8c70c8a", "type": "concept", "title": "Role-sets"}], "description": "Students learn how social positions carry expectations, rights, obligations, and relationships to other positions."}, {"id": "777ad781-1b54-4d5a-b70b-6a36ec2f8f20", "type": "subtopic", "title": "Role conflict, strain, and exit", "children": [{"id": "e0ea6c43-678f-4a22-95d2-8b347ea68666", "type": "concept", "title": "Inter-role conflict"}, {"id": "b1a840ad-4a83-404c-803f-78ca4b5fd2c3", "type": "concept", "title": "Intra-role strain"}, {"id": "ec8f05ce-6992-4dd4-9c61-54661c3bf2e7", "type": "concept", "title": "Role exit"}], "description": "This subtopic examines what happens when expectations collide or when people leave identities and positions behind."}, {"id": "5668f3a3-74ca-4cd3-a2d3-f525957d45d7", "type": "subtopic", "title": "Goffman and dramaturgy", "children": [{"id": "c8eba5a9-0223-4c43-bf73-0c7ca18ddf50", "type": "concept", "title": "Presentation of self"}, {"id": "a101373a-b167-417c-93cf-b6fd8a245208", "type": "concept", "title": "Teams and audiences"}, {"id": "dce147a3-f4ec-4789-bef3-c9d61d19dbd5", "type": "concept", "title": "Face-work and embarrassment"}], "description": "Students analyze everyday interaction through performance, impression management, front stage, back stage, and face-work."}]}, {"id": "db923749-7830-4b5c-a11f-1cec3da12fb0", "type": "topic", "title": "Emotion, Affect, and Feeling Rules", "description": "Emotions are personal experiences, but they are also socially patterned, named, managed, and judged. This unit introduces sociological theories of emotion and emotional labor.", "children": [{"id": "f7e23963-7b4c-4ef3-b637-2f346e000f0f", "type": "subtopic", "title": "Emotion as social and cultural", "children": [{"id": "0dac0a40-1f48-4e53-8b33-0b7787c6d941", "type": "concept", "title": "Emotion vocabularies"}, {"id": "033a9764-99db-43db-9d48-ef017b65dc6c", "type": "concept", "title": "Cultural feeling rules"}, {"id": "e1748263-e32a-44e1-92fd-58ee242ac5cc", "type": "concept", "title": "Display rules"}], "description": "Students learn how societies shape what people feel, display, suppress, and interpret."}, {"id": "93708163-2fa6-4e89-b768-401523a7dd15", "type": "subtopic", "title": "Emotional labor", "children": [{"id": "efef7878-aa37-4308-b657-899668e60055", "type": "concept", "title": "Surface acting"}, {"id": "84b134df-bd88-4bc8-b54a-2d74708e194a", "type": "concept", "title": "Deep acting"}, {"id": "e54764bc-e533-401f-ba69-6ccde39cd1ef", "type": "concept", "title": "Burnout and alienation"}], "description": "This subtopic examines how workers manage feelings as part of service, care, leadership, and institutional roles."}, {"id": "fdfec16c-b2b1-426b-81dd-41b517144cae", "type": "subtopic", "title": "Emotion in groups and movements", "children": [{"id": "6aee12a9-d094-4346-b762-a0af8bcb88b8", "type": "concept", "title": "Collective emotion"}, {"id": "512b266d-506d-4887-b365-3b2796cd1dc3", "type": "concept", "title": "Moral shocks"}, {"id": "364a54a2-694f-4450-8732-757d68100b87", "type": "concept", "title": "Emotional energy"}], "description": "Students study how fear, shame, anger, pride, hope, and solidarity circulate through groups and publics."}]}, {"id": "a27b42d3-1460-4f81-b0e5-8f291ceaed86", "type": "topic", "title": "Attitudes, Values, Beliefs, and Persuasion", "description": "Attitudes and beliefs connect culture, cognition, identity, and action. This unit teaches students how people form, justify, change, and defend evaluations in social settings.", "children": [{"id": "bfef296e-6fe2-42de-9860-43c2e3c1e5d5", "type": "subtopic", "title": "Attitude structure and function", "children": [{"id": "25548887-e589-4cb7-83c7-68cd98b51417", "type": "concept", "title": "Cognitive, affective, and behavioral components"}, {"id": "60646e30-ce68-45c4-9bb3-ca8bd776332d", "type": "concept", "title": "Attitude strength"}, {"id": "46779f42-7273-46b5-8396-e71f0a59f712", "type": "concept", "title": "Values and ideology"}], "description": "Students learn how attitudes organize evaluation, identity, group belonging, and action."}, {"id": "e0a211f1-8f94-4858-b7f7-a67569f4091c", "type": "subtopic", "title": "Persuasion and influence", "children": [{"id": "1722db17-f903-4bcb-88cc-fb003db00873", "type": "concept", "title": "Source, message, and audience"}, {"id": "f6f16b32-d699-4300-8c81-20a79c2e3d7a", "type": "concept", "title": "Central and peripheral routes"}, {"id": "0ca2bd32-5c08-41d6-ad01-a668651cc6fc", "type": "concept", "title": "Credibility and trust"}], "description": "This subtopic introduces major routes of persuasion and the social conditions that make messages effective."}, {"id": "025f5a04-c1a6-4102-bfc3-668abf97a161", "type": "subtopic", "title": "Cognitive dissonance and justification", "children": [{"id": "cfba193d-11aa-40b7-bcd3-1137c82e9608", "type": "concept", "title": "Dissonance reduction"}, {"id": "966a692f-7ee4-4f00-8d13-985c80b6f1d3", "type": "concept", "title": "Self-justification"}, {"id": "1e060770-a017-441a-bbf3-e7c0de330be9", "type": "concept", "title": "Commitment and consistency"}], "description": "Students examine how people reconcile inconsistent beliefs, actions, and identities."}]}, {"id": "5d383f7a-bb54-4eca-88a4-057a1c44ddb7", "type": "topic", "title": "Social Cognition, Attribution, and Categorization", "description": "Sociological social psychology uses cognition carefully: not as isolated mental machinery, but as thinking shaped by culture, groups, institutions, and interaction. This unit develops that bridge.", "children": [{"id": "e6854cca-38ed-43d5-880c-107e9fa6a575", "type": "subtopic", "title": "Schemas and social perception", "children": [{"id": "8168ba35-1225-43e0-84e6-ff14f9aee389", "type": "concept", "title": "Schemas and scripts"}, {"id": "a946f529-a6ee-4e97-b85a-89a4256d0f35", "type": "concept", "title": "Priming and salience"}, {"id": "9d7e697c-eeb4-442e-adfb-5a2ee35509b0", "type": "concept", "title": "Stereotype activation"}], "description": "Students learn how categories, scripts, and expectations guide perception and interpretation."}, {"id": "a0d9d552-26e3-4291-a199-40a995633e3a", "type": "subtopic", "title": "Attribution and explanation", "children": [{"id": "d30e4cfb-b8ca-45ec-b67d-49998202114e", "type": "concept", "title": "Internal and external attribution"}, {"id": "67015972-2cb3-40f6-9396-a4e011242fee", "type": "concept", "title": "Fundamental attribution error"}, {"id": "43f7edca-9a7f-43e5-8c15-a1b6a107b6ac", "type": "concept", "title": "Actor-observer patterns"}], "description": "This subtopic explores how people explain behavior and how those explanations shape blame, trust, and inequality."}, {"id": "ecb9a4b5-e65a-4761-a6b6-53fa13f4d92d", "type": "subtopic", "title": "Bias, heuristics, and social judgment", "children": [{"id": "74077dbd-ca3f-49cf-bca1-6714ba4c7ad6", "type": "concept", "title": "Availability and representativeness"}, {"id": "94972f00-e1e5-49cf-9eb1-d58f09c86108", "type": "concept", "title": "Confirmation bias"}, {"id": "b9a71437-95c2-4739-975d-2b8ea1301762", "type": "concept", "title": "Motivated reasoning"}], "description": "Students examine shortcuts and biases as socially consequential patterns of reasoning."}]}, {"id": "2d0fe5fb-561f-4cbe-8cd8-f031c5f61608", "type": "topic", "title": "Conformity, Compliance, Obedience, and Resistance", "description": "Social influence is central to understanding social order. Students learn why people follow norms, obey authority, comply with requests, and sometimes resist pressure.", "children": [{"id": "0b4e884b-4a27-47d0-97db-f908c942fd19", "type": "subtopic", "title": "Conformity and normative pressure", "children": [{"id": "618bdb86-9b3e-4b3b-821a-3d9c3f72634a", "type": "concept", "title": "Normative influence"}, {"id": "17bc2cda-c63e-44f3-b3d4-bdf6f918de2f", "type": "concept", "title": "Informational influence"}, {"id": "8efd7382-8a82-488d-bc0d-e68df634d898", "type": "concept", "title": "Pluralistic ignorance"}], "description": "Students analyze how group expectations shape behavior, speech, style, and belief."}, {"id": "8e99e7bc-8f3b-4891-9613-43ecbba7adc1", "type": "subtopic", "title": "Compliance and obedience", "children": [{"id": "a3631e3a-392c-486d-bfbd-1d08a1c98dac", "type": "concept", "title": "Authority and legitimacy"}, {"id": "72d782b2-0b28-4044-ab04-60a0b24990f6", "type": "concept", "title": "Foot-in-the-door and door-in-the-face"}, {"id": "69533529-429f-4e9b-8c5e-5be300e684e9", "type": "concept", "title": "Diffusion of responsibility"}], "description": "This subtopic examines how authority, legitimacy, gradual commitment, and institutional setting affect action."}, {"id": "1a48fa22-d216-4e4c-b222-325a8bd7caf8", "type": "subtopic", "title": "Resistance and dissent", "children": [{"id": "199527cd-aed5-4a45-826c-e85e5661a3f2", "type": "concept", "title": "Minority influence"}, {"id": "c9e09907-05be-4993-90ee-b6549b309afd", "type": "concept", "title": "Whistleblowing"}, {"id": "d0d8bda6-8c83-45de-a8ce-9f6cd3b2840b", "type": "concept", "title": "Everyday resistance"}], "description": "Students study how people challenge norms and authority through voice, exit, refusal, and collective action."}]}, {"id": "f1d8cfe8-04f7-4e81-af44-4647f6c14bb3", "type": "topic", "title": "Group Processes, Teams, and Collective Behavior", "description": "Groups are more than collections of individuals. This unit examines how group structure, leadership, cohesion, status, and conflict shape decisions and behavior.", "children": [{"id": "6fcbf12d-fa60-48ff-ba44-4b8792aa3fcc", "type": "subtopic", "title": "Group formation and cohesion", "children": [{"id": "21b4a400-32e3-471f-a84a-ec7881e988f5", "type": "concept", "title": "Membership and boundaries"}, {"id": "fc077eef-aa12-4c99-bdcc-96b3a5de09ec", "type": "concept", "title": "Cohesion and solidarity"}, {"id": "49a68fc8-f739-44e9-8e0d-541eb222fb3f", "type": "concept", "title": "Group identity"}], "description": "Students learn why groups form, how members bond, and when cohesion helps or harms performance."}, {"id": "2cc4ccee-9567-402c-b274-7df4c526ec95", "type": "subtopic", "title": "Leadership, status, and decision-making", "children": [{"id": "47c23294-704d-4b78-a923-df2e6d18a907", "type": "concept", "title": "Leadership styles"}, {"id": "eb42306a-db6e-4cf5-a22d-62050a9a0cf7", "type": "concept", "title": "Status characteristics"}, {"id": "406aa036-5913-440c-86d2-336985fa1eb8", "type": "concept", "title": "Groupthink and polarization"}], "description": "This subtopic studies leadership emergence, status hierarchies, groupthink, polarization, and collective judgment."}, {"id": "fda26adc-985d-48be-b17c-6aabe9985270", "type": "subtopic", "title": "Collective behavior", "children": [{"id": "210d4578-1cb8-4318-bc7b-7b087938f027", "type": "concept", "title": "Emergent norms"}, {"id": "4dc8294b-49a3-4839-ac44-d10236b0d5fb", "type": "concept", "title": "Rumor and contagion"}, {"id": "ba57d3a4-6179-4732-8110-04b53a2c9138", "type": "concept", "title": "Crowds and publics"}], "description": "Students examine crowds, publics, rumors, fads, panics, and emergent group action."}]}, {"id": "4a56334a-c2ad-4d76-97b8-b53ca49534e1", "type": "topic", "title": "Power, Status, Dominance, and Inequality in Interaction", "description": "Power and inequality appear not only in institutions but also in talk, attention, deference, interruption, trust, and evaluation. This unit teaches students to see inequality at the interactional level.", "children": [{"id": "95d0da3f-d686-4365-a64a-62b8f49b7b37", "type": "subtopic", "title": "Status characteristics theory", "children": [{"id": "8907ba29-a81d-4316-9261-ad69c2c3919c", "type": "concept", "title": "Diffuse status characteristics"}, {"id": "1db2f49a-fc55-445b-8e62-20f741f30185", "type": "concept", "title": "Performance expectations"}, {"id": "be2270eb-8ccc-4ee9-9b3e-401179c3fc3b", "type": "concept", "title": "Status generalization"}], "description": "Students learn how status beliefs shape competence expectations and participation in groups."}, {"id": "795faa2f-28ec-4c6a-8627-19bd2ab20413", "type": "subtopic", "title": "Dominance and deference", "children": [{"id": "a2c02112-c6b2-4799-977e-75db8b0dbecc", "type": "concept", "title": "Turn-taking and interruption"}, {"id": "627b5be9-817f-4a3d-bc66-dfc1bb8a00bd", "type": "concept", "title": "Deference and demeanor"}, {"id": "5018b8c1-3f70-462c-9364-3e84b21ef062", "type": "concept", "title": "Spatial and embodied power"}], "description": "This subtopic examines how power is enacted in bodies, language, emotion, space, and interaction rituals."}, {"id": "37e69fdf-845d-423a-bf2f-319d6ac6ea96", "type": "subtopic", "title": "Intersectional interaction", "children": [{"id": "09c344a2-c54c-46ce-995e-e1bc54a1aa1c", "type": "concept", "title": "Microaggressions"}, {"id": "aff54629-c38c-4c2c-b145-ca79b1effce8", "type": "concept", "title": "Stereotype threat"}, {"id": "f05ad1a4-adc8-4af5-b2fa-b7798ffb0767", "type": "concept", "title": "Identity safety"}], "description": "Students analyze how race, class, gender, sexuality, age, disability, and citizenship shape everyday encounters."}]}, {"id": "949dfcc5-d79a-4243-94b8-a555defb029a", "type": "topic", "title": "Prejudice, Stereotyping, Discrimination, and Intergroup Relations", "description": "This unit connects identity, cognition, institutions, and group conflict. Students learn how bias operates at individual, interactional, organizational, and structural levels.", "children": [{"id": "b03d0957-3d81-4394-bf3a-ad9f6477b8c3", "type": "subtopic", "title": "Stereotypes and categorization", "children": [{"id": "8e2d47f3-eed2-42be-9b49-0970e569ecea", "type": "concept", "title": "Stereotype content"}, {"id": "efdba6cb-f3b0-4ce4-8afb-3ec930a61390", "type": "concept", "title": "Implicit and explicit bias"}, {"id": "3dbaabb0-0274-4923-840b-c329c9af4a5f", "type": "concept", "title": "Essentialism"}], "description": "Students examine how categories simplify social worlds and reproduce inequality."}, {"id": "fc86fc3d-682a-45e9-b995-185029805664", "type": "subtopic", "title": "Prejudice and discrimination", "children": [{"id": "091652da-9667-416d-94a7-63dd3419fc70", "type": "concept", "title": "Affective prejudice"}, {"id": "c8a829a8-026a-44ba-a339-f92ed274dd5e", "type": "concept", "title": "Behavioral discrimination"}, {"id": "e41390f5-8b4a-4e5a-8f8f-16ba29b2726c", "type": "concept", "title": "Institutional discrimination"}], "description": "This subtopic distinguishes attitudes, emotions, behaviors, and institutional outcomes."}, {"id": "ada2379b-314b-4208-8826-c1388b0024a7", "type": "subtopic", "title": "Intergroup contact and conflict", "children": [{"id": "5ebea79a-a49b-49b4-8089-9dcf95cbf221", "type": "concept", "title": "Contact hypothesis"}, {"id": "39db3259-c6f7-4e0d-bfd3-a10d534d7329", "type": "concept", "title": "Realistic group conflict"}, {"id": "0c4e79db-b5fc-49f4-8688-7a5956bfcc19", "type": "concept", "title": "Common ingroup identity"}], "description": "Students assess when contact reduces prejudice and when competition or threat intensifies it."}]}, {"id": "a55f6d45-94b8-45bd-adaa-488c2c0bedde", "type": "topic", "title": "Culture, Language, Frames, and Interaction", "description": "Culture gives people repertoires for interpreting situations and acting with others. This unit examines language, frames, narratives, symbols, and cultural toolkits in everyday life.", "children": [{"id": "17459049-84f1-40fd-b3bd-4aaf6c02c48a", "type": "subtopic", "title": "Frames and definitions of the situation", "children": [{"id": "f8196007-1fa3-4ba1-adb4-79545d1a5721", "type": "concept", "title": "Frame alignment"}, {"id": "ac40ec5b-2e61-46d2-8e1a-f19eae360d63", "type": "concept", "title": "Keying and footing"}, {"id": "4e49149b-a951-4cf1-b900-4a2da47dc7af", "type": "concept", "title": "Situational cues"}], "description": "Students learn how frames organize attention, meaning, and appropriate action."}, {"id": "c8b69447-ccf7-41b7-921b-946e497c4eca", "type": "subtopic", "title": "Language and interaction", "children": [{"id": "f06e9e81-15b4-42e5-991c-48ff35da49c7", "type": "concept", "title": "Accounts and excuses"}, {"id": "30971692-c553-4ede-b541-fdf96e97f718", "type": "concept", "title": "Narrative identity"}, {"id": "702d40ec-46ee-43f6-9ee5-3923990e026b", "type": "concept", "title": "Symbolic boundaries"}], "description": "This subtopic studies conversation, categorization, accounts, narratives, and symbolic boundaries."}, {"id": "258d9881-eb3b-4ef8-bb06-69d0a5741483", "type": "subtopic", "title": "Culture as toolkit", "children": [{"id": "dcd4f782-6a9e-4b0d-9a80-24a7c54e9fa4", "type": "concept", "title": "Habits and repertoires"}, {"id": "3b5db67d-c74a-4589-8be0-789a40effc89", "type": "concept", "title": "Cultural capital"}, {"id": "c04f3b2b-2bba-4b62-bd2b-e6cf8edab235", "type": "concept", "title": "Moral vocabularies"}], "description": "Students examine how people draw on cultural repertoires to solve problems and justify action."}]}, {"id": "be4fab72-89b8-4b55-9c13-b01e84e593e8", "type": "topic", "title": "Networks, Social Capital, and Diffusion", "description": "Social life moves through relationships. This unit teaches students how networks shape identity, information, influence, belonging, inequality, and social change.", "children": [{"id": "5af4b9a0-d337-4e20-9b7f-8d6945295661", "type": "subtopic", "title": "Network structure", "children": [{"id": "9ed0c1f3-c511-4d6e-864f-c569337c5d7e", "type": "concept", "title": "Nodes and ties"}, {"id": "53df93b5-fa2a-485f-9579-2324fe83334e", "type": "concept", "title": "Density and centrality"}, {"id": "b239f66b-238a-41f4-9819-f7d3b98dac95", "type": "concept", "title": "Homophily"}], "description": "Students learn basic network ideas and how ties pattern opportunities and constraints."}, {"id": "fb5ec94b-c403-4ce1-b5c6-283dc10f656b", "type": "subtopic", "title": "Social capital and support", "children": [{"id": "2d92e968-949b-4b2b-b7f1-c5a9cb581377", "type": "concept", "title": "Bonding and bridging capital"}, {"id": "f4b10e61-b541-4e67-b71d-62a4b6ef9db4", "type": "concept", "title": "Strong and weak ties"}, {"id": "ef97e90c-484e-45b8-8785-70674d5da413", "type": "concept", "title": "Support and reciprocity"}], "description": "This subtopic examines how relationships provide resources, obligations, trust, and exclusion."}, {"id": "b91ec76a-f4ee-49c4-9178-779cd86022f0", "type": "subtopic", "title": "Diffusion and contagion", "children": [{"id": "dbecbda6-e68c-4c6e-977e-732a92ce07b8", "type": "concept", "title": "Threshold models"}, {"id": "010488c9-1f1b-440c-aa56-49cf21fa1584", "type": "concept", "title": "Opinion leaders"}, {"id": "0617ab3c-42cc-49ef-b19a-888d352fe7eb", "type": "concept", "title": "Network cascades"}], "description": "Students study how ideas, practices, emotions, innovations, and behaviors spread."}]}, {"id": "e4e686db-16e8-4c2b-9f43-1642238da2b0", "type": "topic", "title": "Everyday Life, Organizations, and Institutions", "description": "Sociological social psychology is especially strong at showing how everyday encounters are embedded in organizations and institutions. This unit connects microinteraction with schools, workplaces, medicine, law, religion, and media.", "children": [{"id": "00dea898-fc5d-4a40-a0b8-fed9aa03bfe3", "type": "subtopic", "title": "Organizations as interaction orders", "children": [{"id": "0b23007b-38ef-4ec3-92ab-2b6fe28247fd", "type": "concept", "title": "Workplace roles"}, {"id": "8da2208b-249b-49ec-8315-be08f3059722", "type": "concept", "title": "Professional identity"}, {"id": "e8a4fee7-0579-4af6-8d7b-644afd822542", "type": "concept", "title": "Organizational scripts"}], "description": "Students analyze organizations as settings where roles, emotions, power, and identity are managed."}, {"id": "0e78a4c4-69c1-430d-a525-6953d3de6aaa", "type": "subtopic", "title": "Institutional encounters", "children": [{"id": "0ed05577-dee2-4c62-8da9-ac174c49899e", "type": "concept", "title": "Street-level bureaucracy"}, {"id": "9db9f187-869c-4048-9d2c-22c93ab86597", "type": "concept", "title": "Institutional talk"}, {"id": "2ed44f41-c303-4e2f-a0bf-1c17211b4649", "type": "concept", "title": "Classification and case processing"}], "description": "This subtopic examines interactions with schools, courts, clinics, bureaucracies, and service systems."}, {"id": "d11773f7-8a6a-4db6-bc7f-eba3dd104554", "type": "subtopic", "title": "Media and digital interaction", "children": [{"id": "92c79daf-3242-460c-ab3c-3b0f3c759309", "type": "concept", "title": "Online self-presentation"}, {"id": "639c4848-6816-473a-9864-8488fdb6fd4d", "type": "concept", "title": "Likes and metrics"}, {"id": "f9070ffb-dfe2-463a-87fd-ae5e21b032ba", "type": "concept", "title": "Context collapse"}], "description": "Students explore how platforms reshape self-presentation, attention, comparison, and public identity."}]}, {"id": "cf993c1f-b873-494d-995a-6e081ae30db6", "type": "topic", "title": "Micro-Foundations of Social Movements and Collective Action", "description": "Social movements depend on identity, emotion, networks, framing, solidarity, and strategic interaction. This unit shows how large-scale change rests on small-scale social psychology.", "children": [{"id": "085f30b1-4ffe-4f95-a462-6d585c0ce5eb", "type": "subtopic", "title": "Collective identity", "children": [{"id": "8ee64d71-6cf8-481e-8a6f-63a2dd0bdd67", "type": "concept", "title": "Boundary work"}, {"id": "4def021f-a876-4e28-82d2-df805dfd2ba9", "type": "concept", "title": "Solidarity"}, {"id": "81784457-8bd1-46e0-87d7-5a7967b180b3", "type": "concept", "title": "Identity narratives"}], "description": "Students learn how movements create a shared sense of we, opponents, grievances, and goals."}, {"id": "835ac8d2-eef6-43ec-8ba7-d39d5270a61b", "type": "subtopic", "title": "Mobilization and networks", "children": [{"id": "590008aa-7ffb-429b-9837-35aadfb994f0", "type": "concept", "title": "Recruitment networks"}, {"id": "3bbe1000-e3c1-4ca6-b186-a6ac1d671fdc", "type": "concept", "title": "Biographical availability"}, {"id": "2bbf7ecc-615a-410c-ba5c-c26f1ef561aa", "type": "concept", "title": "Emotional energy"}], "description": "This subtopic examines how ties, organizations, leaders, and emotions draw people into action."}, {"id": "566bf2bb-38fa-4cd1-bd28-8cc193d92937", "type": "subtopic", "title": "Frames, tactics, and outcomes", "children": [{"id": "2325396b-1894-4003-8b1b-80ae9faf425c", "type": "concept", "title": "Diagnostic and prognostic frames"}, {"id": "d31ef967-fa81-4400-b4c8-8ee9814f87f5", "type": "concept", "title": "Repertoires of contention"}, {"id": "a1ff154f-7319-4312-84fc-c61418009289", "type": "concept", "title": "Backlash and countermovements"}], "description": "Students analyze how movements persuade publics, sustain commitment, and face backlash."}]}, {"id": "020b175f-2907-4709-aecc-9a7c5500b662", "type": "topic", "title": "Research Methods for Sociological Social Psychology", "description": "A comprehensive course should teach students not only theories, but how evidence is produced. This unit introduces the main methods used to study interaction, identity, groups, and social influence.", "children": [{"id": "21941521-ded8-4a60-9573-ff2b1c9ebe28", "type": "subtopic", "title": "Surveys, experiments, and mixed methods", "children": [{"id": "3d415a85-db96-4d5e-adac-519b238936e2", "type": "concept", "title": "Survey design"}, {"id": "bc5a5f2c-1f0c-4784-b161-f817fa92995f", "type": "concept", "title": "Experiments and vignettes"}, {"id": "ecc3824f-ba58-45d8-8635-b3d8a4748730", "type": "concept", "title": "Mixed-method designs"}], "description": "Students learn how researchers measure attitudes, identities, networks, influence, and group dynamics."}, {"id": "57eaa26e-0563-46e7-85cf-edcde7c27a89", "type": "subtopic", "title": "Interviews, ethnography, and conversation data", "children": [{"id": "82d09b2f-b32f-49e2-8431-fd72a491658e", "type": "concept", "title": "Interview protocols"}, {"id": "3dbd7bee-17fd-4b3c-bbed-b9886e3fedc4", "type": "concept", "title": "Participant observation"}, {"id": "574a3b6f-4a0f-406c-a5a1-4c6623259b35", "type": "concept", "title": "Conversation and discourse analysis"}], "description": "This subtopic introduces methods for studying meaning, performance, and interaction in depth."}, {"id": "ca35c910-d9d0-4c7a-a3f7-4f814a90054d", "type": "subtopic", "title": "Ethics, replication, and open science", "children": [{"id": "56541cdd-696e-4a75-af5c-251e6a43c15a", "type": "concept", "title": "IRB and consent"}, {"id": "a84e2c8a-0c8b-49ed-8e21-7d0cbde7de8a", "type": "concept", "title": "Preregistration"}, {"id": "184c6c7c-26b9-42df-bf75-8beb0733fa31", "type": "concept", "title": "Data sharing and confidentiality"}], "description": "Students examine human-subjects ethics, transparency, reproducibility, and the responsible interpretation of sensitive findings."}]}, {"id": "a81f654a-8fe1-4fb5-aa77-88a96054df7b", "type": "topic", "title": "Capstone: Interaction Analysis, Identity Case Study, or Group Process Project", "description": "The course culminates in a project where students apply theory and evidence to a real interactional setting, identity process, group dynamic, or social movement. The capstone turns concepts into sociological analysis.", "children": [{"id": "eb33d1c2-f67e-4da1-98e8-b8ed2497f8ae", "type": "subtopic", "title": "Question and theoretical frame", "children": [{"id": "42f7edc4-5f69-46bc-887d-b229cec157e5", "type": "concept", "title": "Research question"}, {"id": "5f0550b6-342d-4d8b-8561-1d731814f511", "type": "concept", "title": "Concept map"}, {"id": "ff512b81-6a32-4420-8a63-5a1d6b71823a", "type": "concept", "title": "Scope and case boundaries"}], "description": "Students define a focused question and choose theories that explain the case."}, {"id": "0070870f-5bc0-45b0-bd7c-4fee9dd3e008", "type": "subtopic", "title": "Evidence portfolio", "children": [{"id": "b2181aa7-0685-475d-a33d-a901cdf0d488", "type": "concept", "title": "Observation or interview evidence"}, {"id": "56a556f3-53fe-41cd-b1c4-1d51cfb6bf88", "type": "concept", "title": "Survey, media, or archival evidence"}, {"id": "bb6a1e03-7232-4bcb-a7c8-817b55827175", "type": "concept", "title": "Ethical documentation"}], "description": "This subtopic requires students to gather empirical material and evaluate its strengths and limits."}, {"id": "72bd5219-3720-4c2b-bc98-c06f8340fc73", "type": "subtopic", "title": "Analysis and public presentation", "children": [{"id": "286df06b-1e2b-452a-aa29-73eba61e5bff", "type": "concept", "title": "Claim-evidence-reasoning"}, {"id": "46d3d9a2-7a69-4aca-8686-8666cf119d03", "type": "concept", "title": "Limitations and reflexivity"}, {"id": "f676cbe6-692b-4798-8653-4f7bd2eaa418", "type": "concept", "title": "Presentation or brief"}], "description": "Students produce a concise research report or presentation linking evidence, theory, and implications."}]}], "dbBacked": true}$spsyjson$::jsonb,
