values
  ('df5c0799-058f-4c6f-93d0-28eba52240af', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', null, 'topic'::public.curated_course_node_type, 'What Makes Social Psychology Sociological', 'This opening unit distinguishes sociological social psychology from individual-centered approaches by emphasizing interaction, roles, culture, identity, power, groups, and social structure. Students learn to explain how selves and actions are shaped through social relations.', 0),
  ('9fb6a4ec-263f-462c-af2d-d23215221764', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'df5c0799-058f-4c6f-93d0-28eba52240af', 'subtopic'::public.curated_course_node_type, 'Micro, meso, and macro connections', 'Students learn how face-to-face interaction connects to organizations, institutions, inequality, and historical context.', 0),
  ('8f4a9d3a-0622-4078-bf7d-62ff7777a659', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '9fb6a4ec-263f-462c-af2d-d23215221764', 'concept'::public.curated_course_node_type, 'Situations and social structure', null, 0),
