  ('f8fc09c1-386c-4b39-8c1d-70d884a50772', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '9fb6a4ec-263f-462c-af2d-d23215221764', 'concept'::public.curated_course_node_type, 'Biography and social history', null, 2),
  ('d21c9477-b35d-4914-b178-644236a9cf4f', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'df5c0799-058f-4c6f-93d0-28eba52240af', 'subtopic'::public.curated_course_node_type, 'Sociological versus psychological emphases', 'This subtopic compares sociological attention to roles, meanings, and groups with psychological attention to individual cognition and traits.', 1),
