  ('1452f1a4-006b-49de-aeaf-86f9fc61c1aa', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'd21c9477-b35d-4914-b178-644236a9cf4f', 'concept'::public.curated_course_node_type, 'Social structure and meaning', null, 1),
  ('e2a7d7c4-e3c6-4617-bd18-7e817c2b2229', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'd21c9477-b35d-4914-b178-644236a9cf4f', 'concept'::public.curated_course_node_type, 'Complementary levels of explanation', null, 2),
