  ('8f8d1ef4-5b4d-4cc0-bf3a-9e4870099848', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '1ce2cd34-7366-4b35-96c2-2c10efdd9e09', 'concept'::public.curated_course_node_type, 'Symbolic interactionism', null, 0),
  ('cb486fb5-af4e-4a91-9a2d-a7c0781c3a09', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '1ce2cd34-7366-4b35-96c2-2c10efdd9e09', 'concept'::public.curated_course_node_type, 'Identity and role theories', null, 1),
  ('b1ccd32e-049d-4ad2-89b5-80767c9e837f', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '1ce2cd34-7366-4b35-96c2-2c10efdd9e09', 'concept'::public.curated_course_node_type, 'Group processes and social influence', null, 2),
  ('a5359511-48f9-4874-80fe-4826dcf106d8', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', null, 'topic'::public.curated_course_node_type, 'Symbolic Interactionism, Meaning, and the Self', 'Symbolic interactionism is a foundation for sociological social psychology. It teaches students how meaning, language, interpretation, and interaction produce selves and social worlds.', 1),
  ('99cb3876-e6b3-416a-871c-9760a06a8b43', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'a5359511-48f9-4874-80fe-4826dcf106d8', 'subtopic'::public.curated_course_node_type, 'Meaning and interpretation', 'Students learn that action depends on meanings people attach to objects, people, situations, and themselves.', 0),
  ('89a3b3b7-f2eb-4b3b-98b0-763a6586b958', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '99cb3876-e6b3-416a-871c-9760a06a8b43', 'concept'::public.curated_course_node_type, 'Symbols and language', null, 0),
  ('7f0284a9-233e-47c8-9fd2-6386c75048fc', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '99cb3876-e6b3-416a-871c-9760a06a8b43', 'concept'::public.curated_course_node_type, 'Definition of the situation', null, 1),
  ('fe7934cb-2d22-4fb9-aad1-a856753122ab', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '99cb3876-e6b3-416a-871c-9760a06a8b43', 'concept'::public.curated_course_node_type, 'Interpretive processes', null, 2),
  ('e8ed9b0c-451e-40a6-9d0a-fdc3cf82697b', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'a5359511-48f9-4874-80fe-4826dcf106d8', 'subtopic'::public.curated_course_node_type, 'Mead: mind, self, and society', 'This subtopic introduces role-taking, the generalized other, and the emergence of the self through social experience.', 1),
  ('e4477b51-3d87-4d6d-8133-67c1ab263d56', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e8ed9b0c-451e-40a6-9d0a-fdc3cf82697b', 'concept'::public.curated_course_node_type, 'I and me', null, 0),
  ('46feb94d-1f26-4424-a6d2-1b9447ac66a8', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e8ed9b0c-451e-40a6-9d0a-fdc3cf82697b', 'concept'::public.curated_course_node_type, 'Role-taking', null, 1),
  ('51037899-6603-4c17-a0fc-ece1396d7d02', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e8ed9b0c-451e-40a6-9d0a-fdc3cf82697b', 'concept'::public.curated_course_node_type, 'Generalized other', null, 2),
  ('48358289-78d1-466e-b6a4-e46aa2af53c1', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'a5359511-48f9-4874-80fe-4826dcf106d8', 'subtopic'::public.curated_course_node_type, 'Blumer and interactionist method', 'Students examine how meanings are negotiated and revised through ongoing interaction.', 2),
  ('6ef8a599-4227-46cc-aac7-a46dd34c4776', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '48358289-78d1-466e-b6a4-e46aa2af53c1', 'concept'::public.curated_course_node_type, 'Joint action', null, 0),
  ('2082f732-d0de-46d5-b9f5-2d23861db873', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '48358289-78d1-466e-b6a4-e46aa2af53c1', 'concept'::public.curated_course_node_type, 'Emergent meanings', null, 1),
  ('99fc247b-b156-44be-ace0-d0db91d1e371', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '48358289-78d1-466e-b6a4-e46aa2af53c1', 'concept'::public.curated_course_node_type, 'Naturalistic inquiry', null, 2),
  ('3ec2db3f-878c-46b4-9dde-7efc6c8582fc', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', null, 'topic'::public.curated_course_node_type, 'Self, Identity, and Self-Concept', 'This unit explores how people develop, maintain, protect, and change identities in relation to others. Students learn to analyze identity as both personal experience and social location.', 2),
  ('269491a4-c14e-4c04-a7d6-c44c79003d45', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '3ec2db3f-878c-46b4-9dde-7efc6c8582fc', 'subtopic'::public.curated_course_node_type, 'Self-concept and reflected appraisals', 'Students learn how people understand themselves through feedback, comparison, and imagined judgments from others.', 0),
  ('4b9c44e9-c9e1-4011-aaae-64d3e78bab3d', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '269491a4-c14e-4c04-a7d6-c44c79003d45', 'concept'::public.curated_course_node_type, 'Looking-glass self', null, 0),
  ('03f8afc4-f58a-4dd5-ba22-bf66c4172338', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '269491a4-c14e-4c04-a7d6-c44c79003d45', 'concept'::public.curated_course_node_type, 'Reflected appraisals', null, 1),
  ('bf6d52f4-53c6-4943-b0ca-31862653a5ac', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '269491a4-c14e-4c04-a7d6-c44c79003d45', 'concept'::public.curated_course_node_type, 'Self-esteem and self-evaluation', null, 2),
  ('e417a142-de1d-426c-ab1c-a52a87e6c919', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '3ec2db3f-878c-46b4-9dde-7efc6c8582fc', 'subtopic'::public.curated_course_node_type, 'Identity theory', 'This subtopic introduces identities as role-based meanings organized in hierarchies of salience and commitment.', 1),
  ('e544eeae-ebc8-4832-bec4-3d9ae96e3558', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e417a142-de1d-426c-ab1c-a52a87e6c919', 'concept'::public.curated_course_node_type, 'Identity salience', null, 0),
  ('b3fce908-3815-40bf-9005-7b4a402a31ba', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e417a142-de1d-426c-ab1c-a52a87e6c919', 'concept'::public.curated_course_node_type, 'Commitment and verification', null, 1),
  ('0264461a-0396-4096-9c59-ddafafcaa698', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e417a142-de1d-426c-ab1c-a52a87e6c919', 'concept'::public.curated_course_node_type, 'Identity standards', null, 2),
  ('d7c03934-ef06-47c5-8e6b-4af8d4c9578b', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '3ec2db3f-878c-46b4-9dde-7efc6c8582fc', 'subtopic'::public.curated_course_node_type, 'Social identity and belonging', 'Students examine how group memberships shape self-understanding, solidarity, bias, and collective behavior.', 2),
  ('9f947ab0-55a4-4984-bb11-e88bc93dd6eb', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'd7c03934-ef06-47c5-8e6b-4af8d4c9578b', 'concept'::public.curated_course_node_type, 'In-groups and out-groups', null, 0),
  ('28f9aecb-7d3e-43ca-89de-3ea6ae2f9596', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'd7c03934-ef06-47c5-8e6b-4af8d4c9578b', 'concept'::public.curated_course_node_type, 'Group identification', null, 1),
  ('48c81d5f-9f75-439e-8cdd-8f6268961631', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'd7c03934-ef06-47c5-8e6b-4af8d4c9578b', 'concept'::public.curated_course_node_type, 'Categorization and belonging', null, 2),
  ('6fe7d5b7-5978-4616-bad9-1c367c5e105b', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', null, 'topic'::public.curated_course_node_type, 'Socialization Across the Life Course', 'Socialization is not only childhood learning; it is a lifelong process through which people acquire, negotiate, and sometimes reject roles, norms, and identities. This unit connects development with institutions and culture.', 3);
