  ('026e80bd-3d14-46d3-bd94-a303f51b0b43', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '6fe7d5b7-5978-4616-bad9-1c367c5e105b', 'subtopic'::public.curated_course_node_type, 'Resocialization and identity change', 'Students study institutions and experiences that actively remake the self.', 2),
