  ('22a78335-ab83-4363-afc1-91c937ef47bf', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '026e80bd-3d14-46d3-bd94-a303f51b0b43', 'concept'::public.curated_course_node_type, 'Conversion and recovery', null, 1),
  ('5d8fb071-3eff-4f20-bd7f-d85dff89c32e', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '026e80bd-3d14-46d3-bd94-a303f51b0b43', 'concept'::public.curated_course_node_type, 'Professional identity formation', null, 2),
  ('66bd3e20-59e0-4ace-bd60-d3fcab468c06', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', null, 'topic'::public.curated_course_node_type, 'Roles, Statuses, and the Interaction Order', 'Roles and statuses organize expectations in everyday life. This unit helps students see interaction as structured performance rather than random behavior.', 4),
