  ('c8eba5a9-0223-4c43-bf73-0c7ca18ddf50', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '5668f3a3-74ca-4cd3-a2d3-f525957d45d7', 'concept'::public.curated_course_node_type, 'Presentation of self', null, 0),
  ('a101373a-b167-417c-93cf-b6fd8a245208', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '5668f3a3-74ca-4cd3-a2d3-f525957d45d7', 'concept'::public.curated_course_node_type, 'Teams and audiences', null, 1),
  ('dce147a3-f4ec-4789-bef3-c9d61d19dbd5', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '5668f3a3-74ca-4cd3-a2d3-f525957d45d7', 'concept'::public.curated_course_node_type, 'Face-work and embarrassment', null, 2),
  ('db923749-7830-4b5c-a11f-1cec3da12fb0', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', null, 'topic'::public.curated_course_node_type, 'Emotion, Affect, and Feeling Rules', 'Emotions are personal experiences, but they are also socially patterned, named, managed, and judged. This unit introduces sociological theories of emotion and emotional labor.', 5),
  ('f7e23963-7b4c-4ef3-b637-2f346e000f0f', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'db923749-7830-4b5c-a11f-1cec3da12fb0', 'subtopic'::public.curated_course_node_type, 'Emotion as social and cultural', 'Students learn how societies shape what people feel, display, suppress, and interpret.', 0),
  ('0dac0a40-1f48-4e53-8b33-0b7787c6d941', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'f7e23963-7b4c-4ef3-b637-2f346e000f0f', 'concept'::public.curated_course_node_type, 'Emotion vocabularies', null, 0),
