  ('e1748263-e32a-44e1-92fd-58ee242ac5cc', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'f7e23963-7b4c-4ef3-b637-2f346e000f0f', 'concept'::public.curated_course_node_type, 'Display rules', null, 2),
  ('93708163-2fa6-4e89-b768-401523a7dd15', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'db923749-7830-4b5c-a11f-1cec3da12fb0', 'subtopic'::public.curated_course_node_type, 'Emotional labor', 'This subtopic examines how workers manage feelings as part of service, care, leadership, and institutional roles.', 1),
  ('efef7878-aa37-4308-b657-899668e60055', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '93708163-2fa6-4e89-b768-401523a7dd15', 'concept'::public.curated_course_node_type, 'Surface acting', null, 0),
  ('84b134df-bd88-4bc8-b54a-2d74708e194a', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '93708163-2fa6-4e89-b768-401523a7dd15', 'concept'::public.curated_course_node_type, 'Deep acting', null, 1),
