  ('6aee12a9-d094-4346-b762-a0af8bcb88b8', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'fdfec16c-b2b1-426b-81dd-41b517144cae', 'concept'::public.curated_course_node_type, 'Collective emotion', null, 0),
  ('512b266d-506d-4887-b365-3b2796cd1dc3', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'fdfec16c-b2b1-426b-81dd-41b517144cae', 'concept'::public.curated_course_node_type, 'Moral shocks', null, 1),
  ('364a54a2-694f-4450-8732-757d68100b87', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'fdfec16c-b2b1-426b-81dd-41b517144cae', 'concept'::public.curated_course_node_type, 'Emotional energy', null, 2),
  ('a27b42d3-1460-4f81-b0e5-8f291ceaed86', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', null, 'topic'::public.curated_course_node_type, 'Attitudes, Values, Beliefs, and Persuasion', 'Attitudes and beliefs connect culture, cognition, identity, and action. This unit teaches students how people form, justify, change, and defend evaluations in social settings.', 6),
