  ('cfba193d-11aa-40b7-bcd3-1137c82e9608', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '025f5a04-c1a6-4102-bfc3-668abf97a161', 'concept'::public.curated_course_node_type, 'Dissonance reduction', null, 0),
