  ('8168ba35-1225-43e0-84e6-ff14f9aee389', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e6854cca-38ed-43d5-880c-107e9fa6a575', 'concept'::public.curated_course_node_type, 'Schemas and scripts', null, 0),
  ('a946f529-a6ee-4e97-b85a-89a4256d0f35', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e6854cca-38ed-43d5-880c-107e9fa6a575', 'concept'::public.curated_course_node_type, 'Priming and salience', null, 1),
  ('9d7e697c-eeb4-442e-adfb-5a2ee35509b0', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'e6854cca-38ed-43d5-880c-107e9fa6a575', 'concept'::public.curated_course_node_type, 'Stereotype activation', null, 2),
  ('a0d9d552-26e3-4291-a199-40a995633e3a', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '5d383f7a-bb54-4eca-88a4-057a1c44ddb7', 'subtopic'::public.curated_course_node_type, 'Attribution and explanation', 'This subtopic explores how people explain behavior and how those explanations shape blame, trust, and inequality.', 1),
