  ('74077dbd-ca3f-49cf-bca1-6714ba4c7ad6', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', 'ecb9a4b5-e65a-4761-a6b6-53fa13f4d92d', 'concept'::public.curated_course_node_type, 'Availability and representativeness', null, 0),
