  ('618bdb86-9b3e-4b3b-821a-3d9c3f72634a', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '0b4e884b-4a27-47d0-97db-f908c942fd19', 'concept'::public.curated_course_node_type, 'Normative influence', null, 0),
