  ('199527cd-aed5-4a45-826c-e85e5661a3f2', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '1a48fa22-d216-4e4c-b222-325a8bd7caf8', 'concept'::public.curated_course_node_type, 'Minority influence', null, 0),
  ('c9e09907-05be-4993-90ee-b6549b309afd', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '1a48fa22-d216-4e4c-b222-325a8bd7caf8', 'concept'::public.curated_course_node_type, 'Whistleblowing', null, 1),
