  ('8ee64d71-6cf8-481e-8a6f-63a2dd0bdd67', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '085f30b1-4ffe-4f95-a462-6d585c0ce5eb', 'concept'::public.curated_course_node_type, 'Boundary work', null, 0),
  ('4def021f-a876-4e28-82d2-df805dfd2ba9', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '085f30b1-4ffe-4f95-a462-6d585c0ce5eb', 'concept'::public.curated_course_node_type, 'Solidarity', null, 1),
