  ('3d415a85-db96-4d5e-adac-519b238936e2', 'c8d9e0f1-2a3b-4d98-9e78-9f0a1b2c3d88', '21941521-ded8-4a60-9573-ff2b1c9ebe28', 'concept'::public.curated_course_node_type, 'Survey design', null, 0),
